      const f = pick(scale) * (Math.random() < 0.25 ? 0.5 : 1);
      tone('sine', f, f, 2.6, 0.035, 0, 0.5); tone('triangle', f * 1.5, f * 1.5, 2.2, 0.012, 0.3, 0.6);
